/// Volatile conditions the engine models, in the order of `VOL_CONDS`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
pub enum VolKind {
    Protect,
    Stall,
    Flinch,
    Confusion,
    Choicelock,
    Gem,
    Metronome,
    Flashfire,
    Unburden,
}

/// Number of `VolKind` variants; a Pokémon can hold at most one of each.
pub const N_VOLATILES: usize = 9;

impl VolKind {
    pub fn id(self) -> &'static str {
        VOL_CONDS[self as usize].id
    }
}

